WITH enriched AS (SELECT *, ROUND(sqft / SUM(sqft) OVER (PARTITION BY region), 4) AS sqft_share, FIRST_VALUE(region) IGNORE NULLS OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region, AVG(sqft) OVER (PARTITION BY region, city ORDER BY sqft, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS sqft_avg_5 FROM stores) SELECT city, DATE_TRUNC('MONTH', opened_date) AS activity_month, region, PERCENTILE_APPROX(sqft, 0.95) AS sqft_p95, COUNT(*) AS num_rows, GROUPING(city) AS grouping_level FROM enriched GROUP BY CUBE (city, DATE_TRUNC('MONTH', opened_date), region) HAVING num_rows > 1;
